function maxRemoval(nums, queries) {
  const n = nums.length;
  queries.sort((a, b) => a[0] - b[0]);
  const heap = [];
  function push(end) {
    heap.push(end);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent] >= heap[child]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  }
  function pop() {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let parent = 0;
      for (;;) {
        const leftChild = 2 * parent + 1;
        const rightChild = leftChild + 1;
        let largest = parent;
        if (leftChild < heap.length && heap[leftChild] > heap[largest]) largest = leftChild;
        if (rightChild < heap.length && heap[rightChild] > heap[largest]) largest = rightChild;
        if (largest === parent) break;
        [heap[parent], heap[largest]] = [heap[largest], heap[parent]];
        parent = largest;
      }
    }
    return top;
  }
  const diff = new Array(n + 1).fill(0);
  let next = 0;
  let cover = 0;
  let used = 0;
  for (let i = 0; i < n; i++) {
    cover += diff[i];
    while (next < queries.length && queries[next][0] <= i) {
      push(queries[next][1]);
      next++;
    }
    while (cover < nums[i]) {
      if (heap.length === 0 || heap[0] < i) {
        return -1;
      }
      const end = pop();
      cover++;
      diff[end + 1]--;
      used++;
    }
  }
  return queries.length - used;
}

