function maxRemoval(nums, queries) {
  // Try every subset of queries to keep: it must cover each index i at least nums[i] times.
  const q = queries.length;
  let best = -1;
  for (let mask = 0; mask < (1 << q); mask++) {
    const count = new Array(nums.length).fill(0);
    let kept = 0;
    for (let j = 0; j < q; j++) {
      if (!(mask & (1 << j))) continue;
      kept++;
      for (let i = queries[j][0]; i <= queries[j][1]; i++) count[i]++;
    }
    if (nums.every((v, i) => count[i] >= v)) best = Math.max(best, q - kept);
  }
  return best;
}

