function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 6);
  const q = large ? 2000 : 1 + Math.floor(rand() * 8);
  const short = rand() < 0.4;
  const queries = [];
  for (let j = 0; j < q; j++) {
    const a = Math.floor(rand() * n);
    const b = short ? Math.min(n - 1, a + Math.floor(rand() * 4)) : Math.floor(rand() * n);
    queries.push([Math.min(a, b), Math.max(a, b)]);
  }
  // Count how many queries cover each index; values use a random share of that count, so all the
  // queries together can zero the array, except that sometimes one value is pushed past its count.
  const diff = new Array(n + 1).fill(0);
  for (const [l, r] of queries) { diff[l]++; diff[r + 1]--; }
  const cover = [];
  let running = 0;
  for (let i = 0; i < n; i++) { running += diff[i]; cover.push(running); }
  const share = rand();
  const nums = cover.map(c => Math.floor(rand() * (c * share + 1)));
  if (rand() < 0.2) {
    const i = Math.floor(rand() * n);
    nums[i] = cover[i] + 1;
  }
  return [nums, queries];
}
